import{_ as i,o as e,c as l,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Установка мода","description":"","frontmatter":{"pageId":"players/install","contentRevision":2},"headers":[],"relativePath":"ru/players/install.md","filePath":"ru/players/install.md"}'),o={name:"ru/players/install.md"};function t(n,a,s,m,d,h){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="установка-мода" tabindex="-1">Установка мода <a class="header-anchor" href="#установка-мода" aria-label="Permalink to &quot;Установка мода&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Скачай архив Rimlink из релиза репозитория. Закрой RimWorld. Распакуй мод так, чтобы каталог Rimlink содержал About и Assemblies, а не ещё одну вложенную папку Rimlink. Установи Harmony 3.x отдельно; релиз Rimlink не включает Harmony.</p><p>Включи Harmony и Rimlink в игровом списке модов, соблюдая порядок зависимостей и указания сервера. Перезапусти игру и проверь наличие пункта <strong>Мультиплеер</strong>. При ошибке загрузки сначала проверь версии и структуру каталогов, затем журнал игры. Набор модов сервера устанавливается отдельно или через предложенный загрузчик.</p><h3 id="установка-из-релиза" tabindex="-1">Установка из релиза <a class="header-anchor" href="#установка-из-релиза" aria-label="Permalink to &quot;Установка из релиза&quot;">​</a></h3><ol><li>Открой <a href="https://github.com/Asofwar/rimlink/releases" target="_blank" rel="noreferrer">релизы Rimlink</a> и выбери архив клиентского мода нужной серверу версии, не сервер и не исходники.</li><li>Закрой RimWorld. В Steam открой <strong>Управление → Просмотреть локальные файлы</strong>. Распакуй Rimlink в каталог <code>Mods</code> внутри игры: должны существовать <code>Mods/Rimlink/About/About.xml</code> и <code>Mods/Rimlink/Assemblies</code>. Двойной вложенности <code>Mods/Rimlink/Rimlink</code> быть не должно.</li><li>Установи отдельный мод Harmony 3.x. Если он из Workshop, запускай игру при работающем Steam. В <strong>Модах</strong> поставь Harmony первым, затем Core и включённые DLC, дальше зависимости/игровые моды и Rimlink по порядку коллекции сервера.</li><li>Включи Rimlink, примени список и перезапусти игру. До подключения проверь пункт <strong>Мультиплеер</strong> в главном меню.</li><li>Подключись к серверу и пройди сверку модпака. Одно появление меню ещё не доказывает совпадение коллекции.</li></ol><p>Если Rimlink отсутствует в списке, проверь вложенность и About. Если виден, но не загружается, проверь RimWorld 1.7, Harmony 3.x и нужный релиз Rimlink; не исправляй ошибку сборки копированием случайных DLL.</p><h2 id="verify-install" tabindex="-1">Как понять, что установлен именно клиентский мод? <a class="header-anchor" href="#verify-install" aria-label="Permalink to &quot;Как понять, что установлен именно клиентский мод? {#verify-install}&quot;">​</a></h2><p>Проверь структуру архива до запуска: папка Rimlink содержит About и Assemblies. Архив сервера с исполняемым файлом .NET не заменяет игровой мод. Не смешивай содержимое разных релизов и не оставляй две активные копии Rimlink.</p><p>После запуска проверь три признака: Rimlink есть в списке модов, зависимости не помечены ошибкой, в главном меню есть «Мультиплеер». После подключения сверка сервера должна завершиться. Последний шаг важен: появление кнопки не доказывает совпадение всей коллекции.</p><p>Если обновление не применяется, закрой игру и проверь, какую папку ты изменяешь. У нескольких установок/профилей разный список модов, а работающий процесс держит DLL. До переустановки сохрани пользовательскую Config и локальные журналы Rimlink; удалять сохранения ради появления кнопки не нужно.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не обновляй DLL при работающей игре. Workshop Harmony может быть недоступен без запущенного Steam. Моды должны иметь разрешение на перераспространение для серверной доставки.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./../compatibility">Версии и совместимость</a></li><li><a href="./modpacks">Набор модов сервера</a></li><li><a href="./troubleshooting">Проблемы игрока</a></li></ul>',16)])])}const k=i(o,[["render",t]]);export{p as __pageData,k as default};
